#include <formatjs/intl/locale.h>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

static double run(const char *tag, const char *options) {
  constexpr int count = 500000;
  auto start = std::chrono::steady_clock::now();
  for (int i = 0; i < count; ++i) {
    FormatjsLocaleHandle *handle = nullptr;
    auto code = formatjs_locale_create(reinterpret_cast<const uint8_t *>(tag), std::strlen(tag), reinterpret_cast<const uint8_t *>(options), std::strlen(options), &handle);
    if (code || !handle) std::abort();
    formatjs_locale_destroy(handle);
  }
  return std::chrono::duration<double, std::nano>(std::chrono::steady_clock::now() - start).count() / count;
}
int main() {
  for (int round = 0; round < 5; ++round) {
    for (auto tag : {"en", "en-x-bench-191", "zh-Hant-HK-u-ca-chinese-nu-hanidec-x-bench-191"}) {
      for (auto opts : round % 2 ? std::initializer_list<const char *>{" { } ", "{}"} : std::initializer_list<const char *>{"{}", " { } "}) {
        std::printf("%d %s %s %.3f\n", round, tag, opts, run(tag, opts));
      }
    }
  }
}
